/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var format = require( '@stdlib/string/format' );

/**
* Method to provide teh safe column number.
* Note: This method provide the column number which present in plot area and does'nt collide with the axis labels and axis.
*
* @private
* @name getSafeRow
* @param {number} pos - position
* @throws {TypeError} - must be a valid pos respective to the plot area
* @returns {void}
*/
function getSafeColumn( pos ) {
	var column;

	// Note: If axis are there then they will acquired there 1 respective space so pos should always the valid according to remaining space
	if ( pos < 0 || pos >= this.plotAreaWidth - this.xAxis - this.yAxis ) {
		throw new TypeError( format( 'invalid option. `%s` must be valid respective to the plot are remaining space. Option: `%s`.', 'position', pos ) );
	}
	column = this.plotArea.x + pos;
	if ( pos >= this.xAxisPos ) {
		column = pos + this.xTicsLabelSpace + 1;
	}

	return column;
}

module.exports = getSafeColumn;
